  steps = $j$[{"type":"email","format":"designed","delay_hours":0.75,"subject":"{{first_name}}, your snacks are still waiting (15% off inside)","subject_variants":["You left something crunchy behind. Here is 15% off","{{first_name}}, we saved your cart and took 15% off"],"preview_text":"Your cart is saved and your own 15% code is inside. Good for 2 days.","preview_variants":["Pick up right where you left off, with 15% off."],"coupon":{"percent_off":15,"expires_in_days":3,"prefix":"CART15"},"coupon_code":"","body_html":"<h1 style=\"margin:0 0 16px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:28px;line-height:1.2;font-weight:400;color:#1A1714;\">Still craving that crunch?</h1><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Hi {{first_name}}, your snacks are still in your cart. Finish your order in the next 2 days and your own 15% off code is on us.</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:8px 0 24px;\"><tr><td bgcolor=\"#AF272F\" align=\"center\" style=\"background:#AF272F;border:2px solid #AF272F;border-radius:14px;\"><a href=\"{{checkout_url}}\" style=\"display:block;text-align:center;padding:18px 20px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:16px;line-height:1.2;font-weight:400;letter-spacing:1px;text-transform:uppercase;color:#FFFFFF;text-decoration:none;border-radius:14px;\">Complete my order</a></td></tr></table>{{cart_items}}{{cart_summary}}<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:8px 0 24px;\"><tr><td bgcolor=\"#F4F1EA\" style=\"background:#F4F1EA;border:2px dashed #AF272F;border-radius:14px;padding:20px;text-align:center;\"><div style=\"font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:18px;line-height:1.3;font-weight:400;color:#1A171