F;border:2px solid #AF272F;border-radius:14px;\"><a href=\"{{checkout_url}}\" style=\"display:block;text-align:center;padding:18px 20px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:16px;line-height:1.2;font-weight:400;letter-spacing:1px;text-transform:uppercase;color:#FFFFFF;text-decoration:none;border-radius:14px;\">Complete my order</a></td></tr></table>"},{"type":"email","format":"designed","delay_hours":24,"subject":"Last chance: your 15% off ends tomorrow","subject_variants":["{{first_name}}, your cart and your 15% code expire tomorrow","Final reminder: your PROMUNCH cart is still saved"],"preview_text":"Your 15% code {{coupon_code}} still works, but not for long.","preview_variants":["This is the last email we will send about your cart."],"coupon":{"percent_off":15,"expires_in_days":3,"prefix":"CART15"},"coupon_code":"","body_html":"<h1 style=\"margin:0 0 16px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:28px;line-height:1.2;font-weight:400;color:#1A1714;\">Last call: your 15% off ends tomorrow</h1><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Hi {{first_name}}, this is the last email we will send about your cart. Your 15% code still works, but only until tomorrow.</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:8px 0 24px;\"><tr><td bgcolor=\"#AF272F\" align=\"center\" style=\"background:#AF272F;border:2px solid #AF272F;border-radius:14px;\"><a href=\"{{checkout_url}}\" style=\"display:block;text-align:center;padding:18px 20px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:16px;line-height:1.2;font-weight:400;letter-spacing:1px;text-transform:uppercase;color:#FFFFFF;text-decoration:none;border-radius:14px;\">Complete my order</a></td></tr></table>{{cart_items}}{{cart_summary}}<table role=\"presentation\" w