-- ============================================================
insert into flows (name, description, trigger_type, trigger_config, steps, status)
select 'Post-purchase', 'First order only. A human thank-you (no order details, Shopify and WhatsApp already confirm), then a how-to guide with the FAQ. Reviews have their own flow.', 'order_placed', $j${"first_order_only":true}$j$::jsonb, $j$[{"type":"email","format":"designed","from_name":"Parth from PROMUNCH","delay_hours":0.25,"bypass_freq_cap":true,"subject":"Thank you, {{first_name}} (this is not a receipt)","subject_variants":["A quick thank you from a real human at PROMUNCH","You just made our day, {{first_name}}"],"preview_text":"No order details here, just a thank you.","preview_variants":["Parth here, founder of PROMUNCH."],"body_html":"<p style=\"margin:0 0 8px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;line-height:1.4;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#AF272F;\">A note from our founder</p><h1 style=\"margin:0 0 16px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:28px;line-height:1.2;font-weight:400;color:#1A1714;\">Thank you, {{first_name}}</h1><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Parth here, I'm the founder of PROMUNCH. Your order confirmation is already with you, so this is not another receipt. I just wanted to say thank you.</p><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">You picked a small Indian snack brand to try, and that genuinely means a lot to us. We built PROMUNCH because savoury snacks with real protein were so hard to find, and every order helps us make more of them.</p><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\"><strong>One tip while you wait:</strong> once a pack is open, seal it tight so the crunch stays crunchy.</p><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">If anything is not right with your order, <strong>just reply to this email</strong> and we will sort it out.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:20px 0 8px;\"><tr><td width=\"76\" valign=\"middle\" style=\"width:76px;padding:0 14px 0 0;\"><img src=\"https://admin.promunch.in/email/parth-headshot.jpg\" width=\"64\" height=\"64\" alt=\"Parth Mutha\" style=\"display:block;width:64px;height:64px;border-radius:32px;border:2px solid #AF272F;object-fit:cover;\"></td><td valign=\"middle\" style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.4;color:#1A1714;\"><strong>Parth Mutha</strong><br><span style=\"font-size:14px;color:#4A453F;\">Founder, PROMUNCH</span><br><span style=\"font-size:13px;font-weight:700;letter-spacing:.5px;color:#AF272F;\">Forbes 30 Under 30 Asia 2025</span></td></tr></table>"},{"type":"email","format":"designed","delay_hours":71.75,"subject":"How to get the most out of your PROMUNCH","subject_variants":["5 ways to enjoy your PROMUNCH snacks","Your PROMUNCH questions, answered"],"preview_text":"Storage, serving ideas and the protein facts.","preview_variants":["A 1 minute guide to your snacks."],"body_html":"<h1 style=\"margin:0 0 16px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:28px;line-height:1.2;font-weight:400;color:#1A1714;\">Your 1 minute snack guide</h1><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Hi {{first_name}}, your PROMUNCH should be with you soon, if it is not already. Here is how to get the most out of it.</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:0 0 14px;\"><tr><td bgcolor=\"#F4F1EA\" style=\"background:#F4F1EA;border-radius:14px;padding:18px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:0 0 14px;\"><img src=\"https://cdn.shopify.com/s/files/1/0794/6731/5501/files/Image_25.jpg?v=1771656794&amp;width=560\" width=\"508\" alt=\"A PROMUNCH jar on the table\" style=\"display:block;width:100%;max-width:508px;height:auto;border-radius:10px;\"></td></tr><tr><td><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;line-height:1.4;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#AF272F;margin:0 0 6px;\">1. Keep it crunchy</div><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Once a pack is open, seal it tight or tip it into an airtight jar, and keep it somewhere cool and dry.</div></td></tr></table></td></tr></table><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:0 0 14px;\"><tr><td bgcolor=\"#F4F1EA\" style=\"background:#F4F1EA;border-radius:14px;padding:18px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:0 0 14px;\"><img src=\"https://cdn.shopify.com/s/files/1/0794/6731/5501/files/All-4-Chunks_Recipes_03_1d491195-6a1d-407d-acba-207266660c9c.jpg?v=1771656794&amp;width=560\" width=\"508\" alt=\"Enjoy PROMUNCH in bhel, upma, soup and salad\" style=\"display:block;width:100%;max-width:508px;height:auto;border-radius:10px;\"></td></tr><tr><td><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;line-height:1.4;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#AF272F;margin:0 0 6px;\">2. Ways to enjoy it</div><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Straight from the pack, or mixed into bhel, upma, soup and salad. It also travels well in your bag for the office or after a workout.</div></td></tr></table></td></tr></table><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:0 0 14px;\"><tr><td bgcolor=\"#F4F1EA\" style=\"background:#F4F1EA;border-radius:14px;padding:18px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:0 0 14px;\"><img src=\"https://cdn.shopify.com/s/files/1/0794/6731/5501/files/rock_salt_comparison_1.jpg?v=1781941697&amp;width=560\" width=\"508\" alt=\"Protein per 100g: PROMUNCH Edamame 45.3g, makhana 7.8g, potato chips 7.2g, peanuts 23.1g\" style=\"display:block;width:100%;max-width:508px;height:auto;border-radius:10px;\"></td></tr><tr><td><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;line-height:1.4;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#AF272F;margin:0 0 6px;\">3. How much protein?</div><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Per 100g, our Himalayan Rock Salt Edamame has <strong>45.3g of protein</strong>. Makhana has 7.8g, potato chips 7.2g and peanuts 23.1g. That is the gap we built PROMUNCH to fill.</div></td></tr></table></td></tr></table><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:0 0 14px;\"><tr><td bgcolor=\"#F4F1EA\" style=\"background:#F4F1EA;border-radius:14px;padding:18px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:13px;line-height:1.4;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#AF272F;margin:0 0 6px;\">4. What is in the pack</div><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;li