able role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:8px 0 20px;\"><tr><td align=\"center\" style=\"text-align:center;\"><div style=\"font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:14px;line-height:1.5;color:#4A453F;margin:0 0 6px;\">Follow the crunch <b style=\"color:#1A1714;\">@promunch.snacks</b></div><a href=\"https://www.instagram.com/promunch.snacks\" style=\"display:inline-block;margin:4px 6px;padding:8px 14px;border:1px solid #AF272F;border-radius:14px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:14px;font-weight:700;color:#AF272F;text-decoration:none;\">Instagram</a><a href=\"https://www.facebook.com/promunch.snacks\" style=\"display:inline-block;margin:4px 6px;padding:8px 14px;border:1px solid #AF272F;border-radius:14px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:14px;font-weight:700;color:#AF272F;text-decoration:none;\">Facebook</a><a href=\"https://www.youtube.com/@PromunchYourMunchyPal\" style=\"display:inline-block;margin:4px 6px;padding:8px 14px;border:1px solid #AF272F;border-radius:14px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:14px;font-weight:700;color:#AF272F;text-decoration:none;\">YouTube</a></td></tr></table>"}]$j$::jsonb, 'draft'
