-- ============================================================
-- B. SUNSET UNENGAGED (segment_entry, draft)
--   5+ marketing emails in 90 days and no open or click. One email: keep me subscribed, or unsubscribe. No discount. Protects sender reputation.
--    1. +0 min      no code                    "Should we stop emailing you, {{first_name}}?"
-- ============================================================
insert into flows (name, description, trigger_type, trigger_config, steps, status)
select 'Sunset unengaged', '5+ marketing emails in 90 days and no open or click. One email: keep me subscribed, or unsubscribe. No discount. Protects sender reputation.', 'segment_entry', $j${"segment":"sunset","min_sends":5,"lookback_days":90}$j$::jsonb, $j$[{"type":"email","format":"designed","delay_hours":0,"subject":"Should we stop emailing you, {{first_name}}?","subject_variants":["Do you still want to hear from PROMUNCH?","Quick question about your inbox"],"preview_text":"One tap to stay. Or unsubscribe, no hard feelings.","preview_variants":["We only want to be in your inbox if you want us there."],"body_html":"<h1 style=\"margin:0 0 16px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:28px;line-height:1.2;font-weight:400;color:#1A1714;\">Should we stop emailing you?</h1><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Hi {{first_name}}, we noticed you have not opened our emails in a while. We only want to be in your inbox if you want us there.</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:8px 0 24px;\"><tr><td bgcolor=\"#AF272F\" align=\"center\" style=\"background:#AF272F;border:2px solid #AF272F;border-radius:14px;\"><a href=\"https://promunch.in/collections/all?utm_source=email&amp;utm_medium=flow&amp;utm_campaign=sunset&amp;utm_content=email_1\" style=\"display:block;text-align:center;padding:18px 20px;font-family:'Archivo Black','Arial Black',Arial,Helvetica,sans-serif;font-size:16px;line-height:1.2;font-weight:400;letter-spacing:1px;text-transform:uppercase;color:#FFFFFF;text-decoration:none;border-radius:14px;\">Yes, keep me subscribed</a></td></tr></table><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Tap the button and you stay on the list. It opens our store, no need to buy anything.</p><p style=\"margin:0 0 16px;font-family:Assistant,'Helvetica Neue',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#1A1714;\">Not for you anymore? Use the unsubscribe link at the bottom of this email. One tap and you are off the list, no hard feelings.</p>"}]$j$::jsonb, 'draft'
where not exists (select 1 from flows where name = 'Sunset unengaged' and trigger_type = 'segment_entry');

commit;

